public class RangeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Range swapped = new Range(5, 2);
        check("new Range(5, 2).lo()", 2, swapped.lo());
        check("new Range(5, 2).hi()", 5, swapped.hi());
        check("swapped range equals in-order range", new Range(2, 5), swapped);
        check("contains hi endpoint", true, new Range(1, 4).contains(4));
        check("contains outside value", false, new Range(1, 4).contains(0));
        check("length of [2, 7]", 5, new Range(2, 7).length());
        check("touching ranges overlap", true, new Range(1, 3).overlaps(new Range(3, 5)));
        check("separated ranges do not overlap", false, new Range(1, 2).overlaps(new Range(4, 6)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

