public record Range(int lo, int hi) {

    public Range {
        if (lo > hi) {
            int tmp = lo;
            lo = hi;
            hi = tmp;
        }
    }

    public boolean contains(int value) {
        return value >= lo && value <= hi;
    }

    public int length() {
        return hi - lo;
    }

    public boolean overlaps(Range other) {
        return lo <= other.hi && other.lo <= hi;
    }
}
